<?php get_header(); while (have_posts()) : the_post(); $id = get_the_ID(); ?>
<main id="main" class="shell profile-main"><a class="back-link" href="<?php echo esc_url(ag_url('artists')); ?>">← All artists</a><div class="profile-layout"><div class="profile-art-column"><?php ag_art($id, 'profile-art', true); ?><p class="art-credit"><?php echo esc_html(ag_meta('artwork_credit') ?: 'Original abstract artwork · Not a photograph of the artist'); ?></p><div class="listen-panel"><p class="eyebrow">TAKE THE NEXT STEP</p><h2>Let the music speak.</h2><?php ag_listen($id); ?></div></div><div class="profile-copy"><p class="eyebrow">ON OUR RADAR / ARTIST PROFILE</p><div class="profile-title"><h1><?php the_title(); ?></h1><?php ag_save_button($id, 'large-save'); ?></div><div class="tag-list"><?php foreach (['genre', 'mood', 'country'] as $tax) { $terms = get_the_terms($id, $tax); foreach ($terms && !is_wp_error($terms) ? $terms : [] as $term) { echo '<a class="tag" href="' . esc_url(ag_url('artists') . '?filter_' . $tax . '=' . $term->slug) . '">' . esc_html($term->name) . '</a>'; } } ?></div><p class="profile-intro"><?php echo esc_html(get_the_excerpt()); ?></p><?php ag_demo_notice($id); ?><div class="prose"><?php the_content(); ?></div>
<?php $recommended = ag_related_ids($id, 'recommended'); if ($recommended) : ?><section class="profile-section"><p class="eyebrow">YOUR WAY IN</p><h2>Start with these songs.</h2><div class="song-list"><?php foreach ($recommended as $i => $song) { ag_song_row($song, sprintf('%02d', $i + 1)); } ?></div></section><?php endif; ?>
<?php $links = ag_source_links($id); $social = ag_source_links($id, 'social'); if ($links || $social || ag_meta('website')) : ?><section class="profile-section"><h2>Further listening & reading.</h2><ul class="source-list"><?php if (ag_meta('website')) { echo '<li><a href="' . esc_url(ag_meta('website')) . '" target="_blank" rel="noopener noreferrer">Official website ↗</a></li>'; } foreach (array_merge($links, $social) as $link) { echo '<li><a href="' . esc_url($link[1]) . '" target="_blank" rel="noopener noreferrer">' . esc_html($link[0]) . ' ↗</a></li>'; } ?></ul></section><?php endif; ?></div></div>
<?php $related = ag_related_ids($id); if ($related) : ?><section class="section related-section"><?php ag_section_heading('FOLLOW THE FEELING', 'If this connects, try these.'); ?><div class="related-grid"><?php $notes = []; foreach (explode("\n", ag_meta('similarity')) as $line) { $p = explode('|', $line, 2); if (count($p) === 2) { $notes[absint($p[0])] = trim($p[1]); } } foreach ($related as $other) : ?><div><?php ag_card($other); ?><p class="similarity-note"><?php echo esc_html($notes[$other] ?? 'A hand-picked editorial connection. Explore and see how it feels to you.'); ?></p></div><?php endforeach; ?></div></section><?php endif; ?>
</main><?php endwhile; get_footer(); ?>
